import{_ as e,o as r,c as t,a4 as i}from"./chunks/framework.Co6Rcm-5.js";const b=JSON.parse('{"title":"Agent 研究雷达","description":"从 2026-03-05 arXiv 日报与 2026-03-03 GitHub Trending 中提炼的阶段性趋势。","frontmatter":{"title":"Agent 研究雷达","description":"从 2026-03-05 arXiv 日报与 2026-03-03 GitHub Trending 中提炼的阶段性趋势。"},"headers":[],"relativePath":"agents/research-radar.md","filePath":"agents/research-radar.md","lastUpdated":1786332289000}'),n={name:"agents/research-radar.md"};function l(o,a,s,d,h,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="agent-研究雷达" tabindex="-1">Agent 研究雷达 <a class="header-anchor" href="#agent-研究雷达" aria-label="Permalink to “Agent 研究雷达”">​</a></h1><p>这一页是时间快照，不是长期定论。材料分别来自 2026-03-05 的 arXiv AI 论文日报和 2026-03-03 的 GitHub Trending 技术报告。</p><h2 id="论文侧的四条信号" tabindex="-1">论文侧的四条信号 <a class="header-anchor" href="#论文侧的四条信号" aria-label="Permalink to “论文侧的四条信号”">​</a></h2><ol><li><strong>多 Agent 拓扑开始进入可学习对象。</strong> Graph-GRPO、CARD 等工作不再只固定协作结构，而是研究拓扑选择与稳定训练。</li><li><strong>检索与策略优化进一步融合。</strong> RAPO、Search-R2 等方向把“何时检索、如何筛选证据”纳入策略和奖励，而不是只把搜索当外部 API。</li><li><strong>长程任务需要层级策略。</strong> HiMAC 一类工作区分宏观规划与微观执行，说明单一逐 token 策略难以覆盖长时间尺度。</li><li><strong>评估平台的重要性上升。</strong> MOSAIC、自动补丁系统研究反映出跨范式对比、真实环境验证和可重复评估正在成为核心基础设施。</li></ol><h2 id="开源项目侧的工程信号" tabindex="-1">开源项目侧的工程信号 <a class="header-anchor" href="#开源项目侧的工程信号" aria-label="Permalink to “开源项目侧的工程信号”">​</a></h2><p>原 GitHub Trending 报告把项目按 Agent 框架、MCP / 工具生态、模型应用和开发工具分类。对内部 Agent 平台最值得保留的不是某个榜单名次，而是三类工程模式：</p><ul><li>Monorepo 与子包边界怎样承载快速变化的 Agent 模块；</li><li>MCP 等协议怎样接入工具，同时保留权限、审计和失败回退；</li><li>UI、会话状态与执行轨迹怎样形成可观测的产品闭环。</li></ul><h2 id="使用限制" tabindex="-1">使用限制 <a class="header-anchor" href="#使用限制" aria-label="Permalink to “使用限制”">​</a></h2><ul><li>日报只覆盖一天的 arXiv 新增，不能代表完整研究版图。</li><li>Trending 受短期传播与社区热度影响，不等于技术成熟度。</li><li>进入项目选型前，必须重新核对当前版本、维护活跃度、许可证和真实 benchmark。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/arXiv-AI-2026-03-05-31a3a54bd6b481bcabc5fa6b973c722b" target="_blank" rel="noreferrer">Notion：arXiv AI 论文日报 2026-03-05</a></li><li><a href="https://app.notion.com/p/GitHub-Trending-2026-03-03-3183a54bd6b4810b91cece6da8f5a7f1" target="_blank" rel="noreferrer">Notion：GitHub Trending 技术报告 2026-03-03</a></li></ul>',11)])])}const p=e(n,[["render",l]]);export{b as __pageData,p as default};
